import React from "react";
import PostsStore from "../../store/PostsStore";
import { PostItem } from "../PostItem/PostItem";

export const PostList = () => {
  return (
    <>
      {PostsStore.posts.map((post, index) => (
        <PostItem key={index}></PostItem>
      ))}
    </>
  );
};
